export default async function install(app) {
  const reactiveUtils = await app.import("esri/core/reactiveUtils");
  const pdmp = app.layers[app.config.pdmpLayerId];
  const trend = app.layers[app.config.trendLayerId];
  app.assert(pdmp && trend, "The CSMP and trend layers are required.");
  await Promise.all([pdmp.load(), trend.load()]);
  const mounts = Object.fromEntries(["naloxone-total","gender-pie","payment-chart","drug-class-chart","schedule-chart","mme-chart","days-supply-chart","county-list","trend-chart"].map((id) => [id, app.getMount(id)]));
  let selected = new Set();
  let activeDrug = null;
  let generation = 0;
  const colors = ["var(--app-series-1)","var(--app-series-2)","var(--app-series-3)","var(--app-series-4)","var(--app-series-5)","var(--app-series-6)"];
  const ns = "http://www.w3.org/2000/svg";
  const el = (tag, text) => { const x = document.createElement(tag); if (text !== undefined) x.textContent = text; return x; };
  const svgEl = (tag) => document.createElementNS(ns, tag);
  const clear = (root) => root.replaceChildren();
  const comma = (v) => Math.round(Number(v || 0)).toLocaleString();
  const whereFor = () => selected.size ? `county IN (${[...selected].map((v) => `'${String(v).replaceAll("'", "''")}'`).join(",")})` : "1=1";
  const baseQuery = (layer) => { const q = layer.createQuery(); q.where = whereFor(); q.geometry = app.view.extent; q.spatialRelationship = "intersects"; q.returnGeometry = false; return q; };
  function styleRoot(root) { root.style.cssText = "width:100%;min-width:0;padding:8px;box-sizing:border-box;font:12px/1.35 system-ui,sans-serif;color:var(--app-text);"; }
  function statQuery(fields) { const q = baseQuery(pdmp); q.outStatistics = fields.map((field) => ({ statisticType: "sum", onStatisticField: field, outStatisticFieldName: field })); return pdmp.queryFeatures(q).then((r) => r.features[0]?.attributes || {}); }
  function chart(root, values, { percent = false } = {}) {
    clear(root); styleRoot(root);
    const rows = Object.entries(values).map(([name,value]) => ({ name, value: Number(value || 0) })).sort((a,b) => b.value-a.value);
    if (!rows.length || !rows.some((r)=>r.value)) { root.append(el("div", "No data in the selected counties or map extent.")); return; }
    const max = Math.max(...rows.map((r)=>r.value), 1);
    const box = el("div"); box.style.cssText = "display:grid;gap:6px;";
    rows.forEach((row, i) => { const line = el("div"); line.style.cssText = "display:grid;grid-template-columns:minmax(90px,42%) 1fr auto;gap:7px;align-items:center;"; const label=el("div",row.name); label.style.cssText="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--app-text-muted);"; const track=el("div"); track.style.cssText="height:12px;background:var(--app-border-subtle);border-radius:6px;overflow:hidden;"; const fill=el("div"); fill.style.cssText=`height:100%;width:${Math.max(1,(row.value/max)*100)}%;background:${colors[i%colors.length]};border-radius:6px;`; track.append(fill); const value=el("div", percent ? `${row.value.toFixed(1)}%` : comma(row.value)); value.style.cssText="font-variant-numeric:tabular-nums;text-align:right;"; line.append(label,track,value); box.append(line); }); root.append(box);
  }
  function pie(root, values) { clear(root); styleRoot(root); const rows=Object.entries(values).map(([name,value])=>({name,value:Number(value||0)})).filter((r)=>r.value>0); const total=rows.reduce((s,r)=>s+r.value,0); if (!total) { root.append(el("div","No gender totals in view.")); return; } const wrap=el("div"); wrap.style.cssText="display:flex;align-items:center;gap:14px;"; const s=svgEl("svg"); s.setAttribute("viewBox","0 0 120 120"); s.style.cssText="width:112px;height:112px;flex:none;"; let offset=0; rows.forEach((r,i)=>{ const circle=svgEl("circle"); circle.setAttribute("cx","60");circle.setAttribute("cy","60");circle.setAttribute("r","43");circle.setAttribute("fill","none");circle.setAttribute("stroke",colors[i%colors.length]);circle.setAttribute("stroke-width","22");circle.setAttribute("pathLength","100");circle.setAttribute("stroke-dasharray",`${(r.value/total)*100} ${100-(r.value/total)*100}`);circle.setAttribute("stroke-dashoffset",String(-offset));circle.setAttribute("transform","rotate(-90 60 60)");offset+=(r.value/total)*100;s.append(circle); }); const center=svgEl("text");center.setAttribute("x","60");center.setAttribute("y","57");center.setAttribute("text-anchor","middle");center.setAttribute("font-size","15");center.setAttribute("fill","currentColor");center.textContent="Patients";s.append(center); const legend=el("div"); legend.style.cssText="display:grid;gap:5px;";rows.forEach((r,i)=>{const item=el("div",`${r.name}: ${(r.value/total*100).toFixed(1)}%`);item.style.cssText=`border-left:10px solid ${colors[i%colors.length]};padding-left:6px;`;legend.append(item);});wrap.append(s,legend);root.append(wrap); }
  function indicator(root, value) { clear(root); styleRoot(root); const num=el("div",comma(value));num.style.cssText="font-size:30px;font-weight:700;font-variant-numeric:tabular-nums;";root.append(num,el("div","Within current map extent and selected counties")); }
  async function countyList() { const root=mounts["county-list"]; clear(root); styleRoot(root); const q=baseQuery(pdmp); q.groupByFieldsForStatistics=["county"]; q.orderByFields=["county ASC"]; q.outStatistics=[{statisticType:"count",onStatisticField:pdmp.objectIdField,outStatisticFieldName:"n"}]; const features=(await pdmp.queryFeatures(q)).features; const intro=el("div",`${features.length} county records in view — choose one or more.`); intro.style.cssText="color:var(--app-text-muted);margin-bottom:7px;"; const list=el("div");list.style.cssText="display:grid;gap:3px;max-height:300px;overflow:auto;"; features.forEach((f)=>{const name=String(f.attributes.county||"Unknown");const b=el("button",name);b.type="button";b.style.cssText=`text-align:left;border:1px solid var(--app-border);border-radius:4px;padding:5px 8px;background:${selected.has(name)?"var(--app-accent)":"var(--app-surface-raised)"};color:${selected.has(name)?"white":"var(--app-text)"};cursor:pointer;`;b.addEventListener("click",()=>{if(selected.has(name)) selected.delete(name); else selected.add(name);void refresh();});list.append(b);}); const reset=el("button",selected.size?"Clear county selection":"All counties");reset.type="button";reset.style.cssText="margin-top:8px;padding:6px;border:1px solid var(--app-border);background:var(--app-surface-raised);cursor:pointer;";reset.addEventListener("click",()=>{selected.clear();void refresh();});root.append(intro,list,reset); }
  async function renderTrend() { const root=mounts["trend-chart"]; clear(root); styleRoot(root); const q=baseQuery(trend);q.groupByFieldsForStatistics=["fillyear","drugtype"];q.orderByFields=["fillyear ASC"];q.outStatistics=[{statisticType:"sum",onStatisticField:"TotalDoses",outStatisticFieldName:"doses"}];const features=(await trend.queryFeatures(q)).features;const types=[...new Set(features.map(f=>String(f.attributes.drugtype||"Unknown")))];if(!types.length){root.append(el("div","No trend data in view."));return;} if(activeDrug && !types.includes(activeDrug)) activeDrug=null; const displayed=activeDrug?[activeDrug]:types;const years=[...new Set(features.map(f=>Number(f.attributes.fillyear)))].sort((a,b)=>a-b);const data=new Map();features.forEach(f=>data.set(`${f.attributes.drugtype}|${f.attributes.fillyear}`,Number(f.attributes.doses||0)));const w=680,h=190,p=34,max=Math.max(1,...displayed.flatMap(t=>years.map(y=>data.get(`${t}|${y}`)||0)));const legend=el("div");legend.style.cssText="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:5px;";types.forEach((type,i)=>{const b=el("button",type);b.type="button";b.style.cssText=`padding:3px 7px;border:1px solid ${colors[i%colors.length]};background:${!activeDrug||activeDrug===type?colors[i%colors.length]:"var(--app-surface)"};color:${!activeDrug||activeDrug===type?"white":"var(--app-text)"};cursor:pointer;`;b.addEventListener("click",()=>{activeDrug=activeDrug===type?null:type;void refresh();});legend.append(b);});const s=svgEl("svg");s.setAttribute("viewBox",`0 0 ${w} ${h}`);s.style.cssText="width:100%;height:210px;display:block;";const axis=svgEl("line");axis.setAttribute("x1",String(p));axis.setAttribute("x2",String(w-p));axis.setAttribute("y1",String(h-p));axis.setAttribute("y2",String(h-p));axis.setAttribute("stroke","currentColor");axis.setAttribute("opacity",".45");s.append(axis);years.forEach((year,i)=>{const x=p+i*((w-2*p)/Math.max(1,years.length-1));const text=svgEl("text");text.setAttribute("x",String(x));text.setAttribute("y",String(h-10));text.setAttribute("text-anchor","middle");text.setAttribute("font-size","10");text.textContent=String(year);s.append(text);});displayed.forEach((type,ti)=>{const i=types.indexOf(type);const points=years.map((year,yi)=>{const v=data.get(`${type}|${year}`)||0;const x=p+yi*((w-2*p)/Math.max(1,years.length-1));const y=h-p-(v/max)*(h-2*p);return [x,y];});const path=svgEl("path");path.setAttribute("d",points.map((pt,i)=>`${i?"L":"M"}${pt[0]},${pt[1]}`).join(" "));path.setAttribute("fill","none");path.setAttribute("stroke",colors[i%colors.length]);path.setAttribute("stroke-width","2.5");s.append(path);points.forEach((pt)=>{const c=svgEl("circle");c.setAttribute("cx",String(pt[0]));c.setAttribute("cy",String(pt[1]));c.setAttribute("r","3");c.setAttribute("fill",colors[i%colors.length]);s.append(c);});});root.append(legend,s); }
  async function refresh() { const mine=++generation; try { const a=await statQuery(["Naloxone","Male","Female","Unknown_Gender","P_Insurance","P_Medicaid","P_Medicare","P_Other_Cash_Insurance","P_Private_Pay","P_Workers","P_Military","P_Indian_Nations","C_Opioids","C_Benzodiazepines","C_Stimulants","Sch_CII","Sch_CIII","Sch_CIV","Sch_CV","MME_0_19","MME_20_49","MME_50_89","MME_ge90","D_0_3","D_4_7","D_8_14","D_15_21","D_22_30","DS_g30"]); if(mine!==generation)return; indicator(mounts["naloxone-total"],a.Naloxone);pie(mounts["gender-pie"],{Male:a.Male,Female:a.Female,Unknown:a.Unknown_Gender});chart(mounts["payment-chart"],{Insurance:a.P_Insurance,Medicaid:a.P_Medicaid,Medicare:a.P_Medicare,"Other cash & insurance":a.P_Other_Cash_Insurance,"Private pay":a.P_Private_Pay,"Workers comp":a.P_Workers,Military:a.P_Military,"Indian nations":a.P_Indian_Nations});chart(mounts["drug-class-chart"],{Opioids:a.C_Opioids,Benzodiazepines:a.C_Benzodiazepines,Stimulants:a.C_Stimulants});chart(mounts["schedule-chart"],{CII:a.Sch_CII,CIII:a.Sch_CIII,CIV:a.Sch_CIV,CV:a.Sch_CV});chart(mounts["mme-chart"],{"0–19":a.MME_0_19,"20–49":a.MME_20_49,"50–89":a.MME_50_89,"90+":a.MME_ge90});chart(mounts["days-supply-chart"],{"0–3":a.D_0_3,"4–7":a.D_4_7,"8–14":a.D_8_14,"15–21":a.D_15_21,"22–30":a.D_22_30,"31+":a.DS_g30});await Promise.all([countyList(),renderTrend()]); } catch(error) { if(mine!==generation)return; Object.values(mounts).forEach((root)=>{clear(root);styleRoot(root);root.append(el("div",`Unable to update: ${error.message}`));}); } }
  const h=reactiveUtils.watch(()=>app.view.stationary,(stationary)=>{if(stationary) void refresh();});app.onCleanup(()=>h.remove());await refresh();
}